.agr .adl{padding:2px}.agr .adl .ic{width:17px;height:17px}
@media(min-width:760px){.agr{grid-template-columns:repeat(auto-fill,minmax(220px,1fr))}}
/* compact bottom audio player */
#abar{bottom:calc(86px + env(safe-area-inset-bottom));padding:7px 10px;border-radius:18px;background:var(--cd);color:var(--tx);border:1px solid rgba(201,151,15,.6);box-shadow:0 8px 24px rgba(60,45,10,.22)}
[data-theme=dark] #abar{background:linear-gradient(135deg,#111216,#2a2314);color:#fff;border-color:rgba(var(--gr),.45);box-shadow:0 12px 30px rgba(0,0,0,.5)}
