[data-theme=dark] #abar .spd{color:var(--g2)}
#abar .asv.on{color:var(--gs)}
body.hasab{padding-bottom:170px}body.hasab #sb{bottom:160px}
/* shorts viewer */
.sf{overscroll-behavior:contain}#sv{height:100%;height:100vh;height:100dvh}.ss{touch-action:pan-y}
.sov{position:absolute;inset:0;z-index:2}
.spi{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:68px;height:68px;border-radius:50%;background:rgba(0,0,0,.55);color:#fff;display:none;place-items:center;z-index:2;pointer-events:none}
