.spg{position:absolute;left:0;bottom:0;height:3px;width:0;background:var(--g);z-index:3}

/* ===== v2.12 changes ===== */
/* Shorts: list = small full-frame rows, grid = big one-by-one feed */
.shr{align-items:center;text-align:start;gap:12px}
