.susw{margin:12px 0 0;text-align:center;font-size:13.5px}
.vpop{position:fixed;inset:0;z-index:95;background:rgba(0,0,0,.45);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);display:grid;place-items:center;padding:18px}
.vpc{background:var(--bg);color:var(--tx);border-radius:24px;max-width:520px;width:100%;padding:16px 18px 18px;box-shadow:0 20px 50px rgba(0,0,0,.4);max-height:90vh;overflow:auto}
.vpt{display:flex;justify-content:center;gap:14px;margin-bottom:8px}
.vpa{font-size:30px;line-height:2.1;text-align:center}
.vpx{text-align:center;margin:6px 0}
.stl h4{margin:12px 0 4px;font-size:14px}.stl ul{margin:0 0 6px;padding-inline-start:18px;line-height:1.65;font-size:14px}
.stpk{cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px}
.nav .mid{touch-action:none;-webkit-user-select:none;user-select:none}
.nav .mid .ico{transition:transform .2s,box-shadow .2s}
.nav .mid.arm .ico{transform:scale(1.08)}
body.studm .nav .mid .ico{transform:translateY(-26px) scale(1.16);box-shadow:0 14px 28px rgba(var(--gr),.7)}
.hm{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(100px + env(safe-area-inset-bottom));z-index:24;display:flex;align-items:center;gap:6px;max-width:calc(100% - 28px);padding:6px 6px 6px 12px;border-radius:14px;background:rgba(20,20,24,.9);color:#fff;font-size:12px;line-height:1.35;box-shadow:0 8px 22px rgba(0,0,0,.3);animation:ipin .5s ease both}
.hm:after{content:"";position:absolute;left:50%;bottom:-6px;width:12px;height:12px;background:rgba(20,20,24,.9);transform:translateX(-50%) rotate(45deg);border-radius:2px}
.hm .ib{min-width:26px;width:26px;height:26px;background:transparent;color:#fff;border:0;padding:0}.hm .ib .ic{width:14px;height:14px}
body.playing .hm,body.qp .hm{display:none}

/* ===== v2.22 ===== */
.bsm{text-align:center;padding:14px 0 6px;color:var(--g)}
.vn{display:inline-grid;place-items:center;min-width:1.5em;height:1.5em;padding:0 .25em;margin-inline-start:.4em;border:2px solid var(--g);border-radius:999px;font-size:.48em;line-height:1;color:var(--gt);vertical-align:middle}
[data-theme=dark] .vn{color:var(--g)}
.lnk.gold{color:#c9970f;text-decoration:underline;font-weight:600;font-size:inherit;padding:0}
[data-theme=dark] .lnk.gold{color:var(--g)}
/* ===== Prayer time widget + TV mode ===== */
#pw{display:none;flex:1;min-width:0;justify-content:center}
body.pwon:not(.qp) #pw{display:flex}
#pwb{display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:0;max-width:100%;padding:3px 10px;border-radius:14px;background:var(--cd);border:1px solid var(--bd);color:var(--tx);line-height:1.15;cursor:pointer}
#pwb small{font-size:10px;color:var(--mt);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
#pwb b{font-size:14px;font-weight:800;color:var(--gt);font-variant-numeric:tabular-nums;letter-spacing:.3px;font-family:'Inter',sans-serif}
[data-theme=dark] #pwb b{color:var(--g)}
@media(min-width:600px){#pwb{flex-direction:row;gap:6px;padding:6px 14px}#pwb small{font-size:13px}#pwb small:after{content:":"}#pwb b{font-size:16px}}
@media(max-width:420px){body.pwon:not(.qp) .hd .ib{min-width:36px;width:36px;height:36px}body.pwon:not(.qp) .lw{width:36px;height:36px}body.pwon:not(.qp) .hi{gap:4px;padding-inline:10px}}
body.pton{overflow:hidden}body.pton #tt{z-index:140}
.pt{position:fixed;inset:0;z-index:120;display:flex;flex-direction:column;color:var(--ptx);background:linear-gradient(160deg,var(--pb1),var(--pb2));font-family:var(--ptf),sans-serif;user-select:none;-webkit-user-select:none}
.pt .ptbg,.pt .ptdim{position:absolute;inset:0;background-size:cover;background-position:center}
.pt .ptdim{background:#000;opacity:var(--pdm,0)}
.pt small{font-size:.55em}
.ptm.one{grid-template-columns:1fr!important}
.ptadj{display:grid;grid-template-columns:1fr 44px 52px 44px;gap:6px;align-items:center;margin:6px 0}.ptadj b{text-align:center;color:var(--g)}.ptstp{height:40px;border-radius:12px;border:1px solid #3a3a42;background:#26262c;color:#f3efe2;font-size:20px;cursor:pointer;padding:0}
.ptm{position:relative;flex:1;display:grid;gap:3vmin;padding:6vmin;align-content:center;min-height:0;overflow:hidden}
@media(orientation:landscape){.ptm{grid-template-columns:1.1fr 1fr;align-items:center}}
.ptl{text-align:center;min-width:0}
.ptdt{font-size:2.6vmin;color:var(--psb);margin-bottom:1.5vmin}
.ptclk{font-family:var(--ptd),sans-serif;font-weight:800;font-size:calc(var(--pcs)*.15vmin);line-height:1.05;font-variant-numeric:tabular-nums;white-space:nowrap}
.ptclk i{font-style:normal;font-size:.5em;color:var(--pac);font-weight:700}
.ptclk small{font-size:.32em;color:var(--psb);font-weight:600}
.ptcd{margin-top:2.5vmin;padding:2.5vmin 3vmin;border-radius:3vmin;background:rgba(255,255,255,.1);border:1px solid color-mix(in srgb,var(--pac) 45%,transparent);backdrop-filter:blur(6px)}
#ptcl{font-size:3vmin;color:var(--psb)}
.ptcv{font-family:var(--ptd),sans-serif;font-weight:800;font-size:calc(var(--pcs)*.1vmin);color:var(--pac);font-variant-numeric:tabular-nums;line-height:1.1}
.ptrs{display:grid;gap:1.1vmin;min-width:0}
.ptrw{display:grid;grid-template-columns:1.4fr 1fr 1fr;align-items:center;gap:2vmin;padding:1.4vmin 2.4vmin;border-radius:2.4vmin;background:rgba(255,255,255,.07);font-size:calc(var(--pps)*.042vmin);border-inline-start:.9vmin solid transparent}
.ptrw span{font-family:var(--ptd),sans-serif;font-weight:700;text-align:center;font-variant-numeric:tabular-nums}
.ptrh{background:none;font-size:calc(var(--pps)*.028vmin);color:var(--psb);padding-block:0}
.ptrw.sr{opacity:.7}
.ptrw.nx{background:rgba(255,255,255,.18);border-inline-start-color:var(--pac)}
.ptrw.nx.jm{background:color-mix(in srgb,var(--pac) 30%,transparent)}
.ptn{display:flex;flex-direction:column;min-width:0;line-height:1.15}.ptn b{font-weight:800}.ptn small{font-family:var(--pta),serif;color:var(--psb);font-size:.62em}
.ptan{position:absolute;inset-inline:0;bottom:0;overflow:hidden;white-space:nowrap;padding:1.6vmin 0;background:rgba(0,0,0,.35);font-size:3vmin;color:var(--ptx)}
.ptan span{display:inline-block;padding-inline-start:100%;animation:ptmq 25s linear infinite}
@keyframes ptmq{to{transform:translateX(-100%)}}
[dir=rtl] .ptan span{animation-direction:reverse}
.ptc{position:absolute;inset-inline:0;top:0;display:flex;gap:10px;padding:calc(env(safe-area-inset-top,0px) + 12px) 14px 0;opacity:0;pointer-events:none;transition:opacity .25s;z-index:3}
.pt.ctl .ptc{opacity:1;pointer-events:auto}
.ptcb{display:grid;place-items:center;width:clamp(44px,7vmin,64px);height:clamp(44px,7vmin,64px);border-radius:50%;border:1px solid rgba(255,255,255,.35);background:rgba(0,0,0,.45);color:#fff;cursor:pointer;padding:0}
.ptcb .ic{width:55%;height:55%}.ptcb.sm{width:38px;height:38px}
.ptp{position:absolute;inset-inline:0;bottom:0;max-height:80%;max-width:640px;margin:0 auto;overflow:auto;background:rgba(18,18,22,.86);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);color:#f3efe2;border-radius:22px 22px 0 0;padding:14px 16px 26px;z-index:4;font-size:15px;font-family:var(--ft),sans-serif;user-select:auto;-webkit-user-select:auto}
.ptp[hidden]{display:none}
.ptph{display:flex;justify-content:space-between;align-items:center;font-size:17px}
.ptp h4{margin:16px 0 6px;color:var(--g);font-size:14px}
.ptp label{display:block;margin:10px 0 4px;font-size:13px;opacity:.9}.ptp label b{color:var(--g);margin-inline-start:6px}
.ptp input,.ptp select,.ptp textarea{width:100%;background:#26262c;color:#f3efe2;border:1px solid #3a3a42;border-radius:12px;padding:9px;font:inherit}
.ptp input[type=range]{padding:0;accent-color:var(--g)}.ptp input[type=color]{height:42px;padding:3px}
.ptp .ptck{display:flex;align-items:center;gap:8px;margin:10px 0}.ptp .ptck input{width:auto}
.ptchs,.ptphs{display:flex;flex-wrap:wrap;gap:8px}
.ptch{border:2px solid transparent;border-radius:12px;padding:9px 12px;font:inherit;font-size:13px;cursor:pointer}.ptch.on{border-color:var(--g)}
.ptcl,.ptgp{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:8px}.ptgp{grid-template-columns:repeat(5,1fr)}.ptgp2{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.ptgp input{padding:8px 4px;text-align:center}.ptgp label{margin:0;font-size:11px;text-align:center}
.ptth{position:relative;width:60px;height:60px}.ptth>button:first-child{width:100%;height:100%;border-radius:12px;border:2px solid #3a3a42;background-size:cover;background-position:center;padding:0}.ptth.on>button:first-child{border-color:var(--g)}
.ptx{position:absolute;top:-6px;inset-inline-end:-6px;width:22px;height:22px;border-radius:50%;border:0;background:#000;color:#fff;display:grid;place-items:center;padding:0}.ptx .ic{width:12px;height:12px}
.ptad{display:grid!important;place-items:center;width:60px;height:60px;margin:0!important;border:2px dashed #3a3a42;border-radius:12px;cursor:pointer}.ptad .ic{width:24px;height:24px}
.ptbt{margin-top:8px;width:100%;padding:10px;border-radius:12px;border:1px solid #3a3a42;background:#26262c;color:#f3efe2;font:inherit;cursor:pointer}
/* ===== glow + ripple FX, word chips ===== */
#th{touch-action:none;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
#thp{position:fixed;z-index:260;padding:8px;border-radius:22px;background:color-mix(in srgb,var(--cd) 62%,transparent);backdrop-filter:blur(24px) saturate(1.5);-webkit-backdrop-filter:blur(24px) saturate(1.5);border:1px solid color-mix(in srgb,var(--g) 45%,transparent);box-shadow:0 18px 40px rgba(0,0,0,.35),0 0 32px rgba(var(--gr),.25);animation:thin .24s cubic-bezier(.2,.9,.3,1.2)}
@keyframes thin{from{opacity:0;transform:translateY(-10px) scale(.92)}}
.thi{display:flex;align-items:center;gap:10px;width:100%;padding:11px 12px;border-radius:14px;color:var(--tx);font-size:15px;text-align:start;justify-content:flex-start;transition:background .12s,transform .12s}
.thi.hl,.thi:active{background:color-mix(in srgb,var(--g) 30%,transparent);transform:scale(1.04)}
.thi.cur span:after{content:" ✓"}
.thd{width:22px;height:22px;border-radius:50%;flex:none;border:1px solid rgba(255,255,255,.4)}
.th-gold{background:linear-gradient(135deg,#F7DE8E,#E3B341)}.th-cream{background:linear-gradient(135deg,#FFFFFF,#F1E8D0)}.th-emerald{background:linear-gradient(135deg,#A7F3D0,#34D399)}.th-ocean{background:linear-gradient(135deg,#BAE6FD,#38BDF8)}.th-dusk{background:linear-gradient(135deg,#FBC9A8,#7a3fa0)}
:root[data-gl][data-theme=dark]{--cd:rgba(255,255,255,.08);--bd:rgba(255,255,255,.18)}
:root[data-gl][data-theme=light]{--cd:rgba(255,255,255,.55);--bd:rgba(255,255,255,.75)}
[data-gl] body{background:radial-gradient(60% 40% at 15% 8%,color-mix(in srgb,var(--g) 38%,transparent),transparent 70%),radial-gradient(50% 40% at 90% 30%,color-mix(in srgb,var(--g2) 30%,transparent),transparent 70%),radial-gradient(60% 45% at 25% 95%,color-mix(in srgb,var(--tx) 14%,transparent),transparent 70%),var(--bg);background-attachment:fixed}
[data-gl] :is(.card,.row,.slide,.intro,.stpn,.vpc,.nav,.hd,input,select,textarea,#thp){backdrop-filter:blur(16px) saturate(1.35);-webkit-backdrop-filter:blur(16px) saturate(1.35)}
.pt[data-gl] :is(.ptcd,.ptrw){backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border:1px solid rgba(255,255,255,.22);background:rgba(255,255,255,.12)}
/* header: logo underline no longer pushes the logo text up, everything is centred */
.lg{position:relative}.lg:after{position:absolute;inset-inline-start:0;bottom:-7px;margin:0!important}
.hi>div{align-items:center}
/* King Fahad Complex fonts: the font's own ayah-end sign, same colour as the verse */
.vn .vk{display:none}
body.kfq .v .vn{display:inline;border:0;min-width:0;height:auto;padding:0;margin:0 .2em;font-size:1em;line-height:inherit;color:inherit;vertical-align:baseline}
body.kfq .v .vn .vc{display:none}body.kfq .v .vn .vk{display:inline;font-family:var(--af)}
/* word by word */
body.wh .v .w{cursor:pointer;border-radius:8px;transition:background .12s}
.v .w.on{background:rgba(var(--gr),.38);box-shadow:0 0 0 3px rgba(var(--gr),.38)}
/* verse menu (reason of revelation / compare) */
.vx{margin:8px 0;padding:10px;border:1px solid var(--bd);border-radius:14px;background:var(--cd)}.vx[hidden]{display:none}
.vxo{display:flex;gap:8px;flex-wrap:wrap}.vxc{margin-top:8px}.vxc .tr{font-size:calc(var(--ts) * .95);margin:8px 0}
.mnset .stchs{display:flex;flex-wrap:wrap;gap:8px}.mnset .stch{padding:8px 14px;border-radius:12px;border:1px solid var(--bd);background:var(--cd);color:var(--tx)}.mnset .stch.on{border-color:var(--g);background:color-mix(in srgb,var(--g) 22%,transparent)}
.mnh{margin:18px 4px 6px;color:var(--g)}.mnset{padding:12px 14px}.mnset .mnh{margin:12px 0 4px}.mnset label{display:block;margin-top:8px}
:root[data-sk=emerald]{--g:#34D399;--g2:#A7F3D0;--gr:52,211,153;--gd:#1f9e73;--gt:#34D399;--gs:#6ee7b7;--bg:#07120f;--cd:#0e1d19;--tx:#e8f5ee;--mt:#8fb3a5;--bd:#1b3a31;--dk:#12251f;--ln:#2c5a4c}
:root[data-sk=ocean]{--g:#38BDF8;--g2:#BAE6FD;--gr:56,189,248;--gd:#1b8fc4;--gt:#38BDF8;--gs:#7dd3fc;--bg:#06101c;--cd:#0d1b2e;--tx:#e6f1fb;--mt:#8fa9c4;--bd:#1b3350;--dk:#10243a;--ln:#2d5278}
:root[data-sk=dusk]{--g:#F59E6C;--g2:#FBC9A8;--gr:245,158,108;--gd:#d9763f;--gt:#F59E6C;--gs:#fbb48f;--bg:#120b1f;--cd:#1c1230;--tx:#f3e9f7;--mt:#a898bd;--bd:#33224d;--dk:#241638;--ln:#4d3a70}
.stwc{display:flex;flex-wrap:wrap;gap:6px;direction:rtl;align-items:center;margin:6px 0 10px;font-size:22px;line-height:1.5}
.stwc .stch{font:inherit;font-size:20px;padding:4px 10px;opacity:.5}.stwc .stch.on{opacity:1}
.stwn{font:600 11px sans-serif;color:var(--mt);padding:2px 6px;border-radius:8px;border:1px solid var(--bd)}
.av{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:linear-gradient(135deg,var(--g2),var(--g));color:#1b1608;font-weight:800;font-size:14px;line-height:1;text-transform:uppercase}
.ppb{width:100%;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 4px;margin-top:6px;border:0;border-top:1px dashed var(--bd);background:none;color:inherit;font:inherit;cursor:pointer;text-align:start}
.ppb .ic{transition:transform .25s}.ppb.open .ic{transform:rotate(180deg)}
.ppx{padding:0 4px 6px}.ppx[hidden]{display:none}.ppx ul{margin:4px 0;padding-inline-start:20px}
.dtop{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.dtop b{flex:1;font-size:17px}.dti{color:var(--gt)}
.dtx{margin:6px 0 16px;line-height:1.8;font-size:15px}
.stpv{position:sticky;top:var(--hh,64px);z-index:12;padding:8px 0 6px;background:var(--bg);text-align:center}
.stpv canvas{height:min(34vh,300px);width:auto;max-width:100%;border-radius:14px;box-shadow:0 6px 18px rgba(0,0,0,.25);background:#000;display:inline-block}
.stpl{position:absolute;top:14px;inset-inline-start:6px;font-size:10px;padding:2px 8px;border-radius:10px;background:rgba(0,0,0,.6);color:#fff}

/* ===== modern-browser enhancements (old browsers keep the solid fallbacks above) ===== */
@supports (background:color-mix(in srgb,red 50%,blue)){
.hd{background:color-mix(in srgb,var(--bg) 80%,transparent)}
.nav{background:color-mix(in srgb,var(--cd) 88%,transparent)}
.pl{background:color-mix(in srgb,var(--bg) 90%,transparent)}
.kct{background:color-mix(in srgb,var(--bg) 92%,transparent)}
.sk{background:linear-gradient(100deg,var(--bd) 30%,color-mix(in srgb,var(--bd) 35%,transparent) 50%,var(--bd) 70%);background-size:200% 100%}
}


.sthd{display:flex;align-items:center;gap:8px;padding:4px 2px 0}
.sthd .ib{width:36px;height:36px;flex:none}
.sthd b{flex:1;min-width:0;font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sthi{display:grid;place-items:center;color:var(--g)}.sthi .ic{width:20px;height:20px}
.stmd{display:flex;gap:4px;flex:none;background:var(--cd);border:1px solid var(--bd);border-radius:12px;padding:3px}
.stmd button{width:38px;height:30px;border:0;border-radius:9px;background:transparent;color:inherit;display:grid;place-items:center;cursor:pointer}
.stmd button.on{background:linear-gradient(135deg,var(--g2),var(--g));color:#1b1608}
.stmd .ic{width:18px;height:18px}
.stpn{max-height:max(160px,calc(100vh - 470px));max-height:max(160px,calc(100dvh - 470px));overflow-y:auto;overscroll-behavior:contain;padding:8px 10px;font-size:13px}
.stpn .stav h4{margin:10px 0 4px;font-size:13px}
.stpn .stav label{margin:6px 0 2px;font-size:12px}
.stpn .stav select,.stpn textarea,.stpn .stav input[type=color]{padding:7px 10px;font-size:13px;border-radius:12px}
.stpn .stav input[type=color]{height:36px}
.stpn p.mu{font-size:12px;margin:4px 0}
.stpn .btn{padding:8px 10px;font-size:13px}
.stpn .two{gap:8px}
.stvrw canvas,#stvrc{width:100%;height:96px;border-radius:12px;display:block;background:#17130a}
.stvrt{text-align:center;font-size:20px;margin:4px 0}
.stvrb{display:flex;justify-content:center;gap:14px;margin:8px 0}
.stvri{width:50px;height:50px;border-radius:50%;border:1px solid var(--bd);background:var(--cd);color:inherit;display:grid;place-items:center;cursor:pointer;padding:0}
.stvri .ic{width:22px;height:22px}
.stvri.rec{background:#e0452f;color:#fff;border-color:transparent}
.stvri.ok{background:#3bb273;color:#fff;border-color:transparent}
.stvri.on{outline:2px solid var(--g)}
.stvro{margin-top:8px}
@media(min-width:900px){#stvrc{height:160px}}

.stbar .stpv canvas{height:var(--stph,160px)}
.stpz{position:absolute;top:10px;right:10px;width:34px;height:34px;border-radius:50%;border:0;background:rgba(0,0,0,.55);color:#fff;display:grid;place-items:center;cursor:pointer;z-index:3}
.stpz .ic{width:16px;height:16px}
.stbar .stpv{padding-inline:4px}
.btn.sm{padding:6px 12px;font-size:12px;min-height:0;width:auto;display:inline-flex;align-items:center;gap:6px}
.btn.sm .ic{width:16px;height:16px}
.stsg{display:flex;gap:4px;background:rgba(128,128,128,.14);border-radius:12px;padding:3px;margin:4px 0 8px}
.stsg button{flex:1;padding:7px 8px;border:0;border-radius:9px;background:transparent;color:inherit;font:inherit;font-size:12px;display:flex;align-items:center;justify-content:center;gap:6px;cursor:pointer}
.stsg button.on{background:var(--cd);box-shadow:0 1px 4px rgba(0,0,0,.18);font-weight:700}
.stsg .ic{width:16px;height:16px}
.stvrx{display:flex;gap:8px;flex-wrap:wrap;margin-top:4px}
.stcf{position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.5);display:grid;place-items:center;padding:20px}
.stcc{background:var(--bg);color:inherit;border-radius:18px;padding:18px;max-width:340px;width:100%;box-shadow:0 10px 40px rgba(0,0,0,.35)}
.stcc p{margin:0 0 14px;font-size:15px;line-height:1.5}
.stcc .two{display:flex;gap:10px}.stcc .btn{flex:1}
.stcc .btn:not(.go){background:transparent;border:1px solid var(--bd);color:inherit}
.stth button:not([style]){background:#1b1608;color:var(--g)}
.stcc .btn.go{background:linear-gradient(135deg,var(--g),var(--gd));color:#1a1405;border-color:transparent;font-weight:700}

.stmode #nv{display:none}
.stmode main{padding-bottom:24px}
.stbar .stpv #stout{display:none;text-align:center}
.stbar .stpv.hasout #stout{display:block}
.stbar .stpv.hasout #stpv,.stbar .stpv.hasout .stpl,.stbar .stpv.hasout .stpz{display:none}
.stbar .stpv #stout video,.stbar .stpv #stout img,.stbar .stpv #stout canvas{max-height:var(--stph,160px);max-width:100%;border-radius:14px;display:block;margin:0 auto}
.stbar .stpv #stout .card{padding:10px;margin:0}
.stbar .stpv #stout .card p{margin:4px 0;font-size:12px}
.stbar .stpv #stout .btn{padding:7px 12px;font-size:12px}
.stbar .stpv #stout .stbt{margin-top:6px;display:flex;gap:8px;justify-content:center}
.stpx{position:absolute;top:8px;right:8px;width:30px;height:30px;border-radius:50%;border:0;background:rgba(0,0,0,.6);color:#fff;display:none;place-items:center;cursor:pointer;z-index:4}
.stpx .ic{width:14px;height:14px}
.stbar .stpv.hasdone .stpx{display:grid}
.stbar .stpv #stout video{width:auto;max-width:100%;height:var(--stph,160px);object-fit:contain}
.stbar .stpv #stout .btn{width:auto;flex:0 0 auto}
.stbar .stpv #stout .stpb{height:8px}
.stbar .stpv #stout .stbt{display:flex;justify-content:center}
/* ===== Studio v3 toolbar (tl* classes) ===== */
.tlbw{display:flex;gap:6px;align-items:stretch;padding:4px 2px}
.tlbs{flex:1;min-width:0;display:flex;gap:6px;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch}
.tlbs::-webkit-scrollbar{display:none}
.tlb{flex:none;min-width:58px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:7px 8px;border:1px solid var(--bd);border-radius:14px;background:var(--cd);color:inherit;font:inherit;font-size:11px;line-height:1.2;white-space:nowrap;cursor:pointer}
.tlb .ic{width:20px;height:20px}
.tlb.on{border-color:var(--g);background:rgba(var(--gr),.18)}
.tlb.tlgo{background:linear-gradient(135deg,var(--g),var(--gd));color:#1a1405;border-color:transparent;font-weight:700}
.stbar{position:sticky;top:var(--hh,64px);z-index:12;background:var(--bg);padding-bottom:6px;border-bottom:1px solid var(--bd)}
.stbar .stpv{position:relative;top:auto;z-index:auto;padding:4px 0}

.stpn{margin:10px 0 16px;padding:12px 14px;border:1px solid var(--bd);border-radius:18px;background:var(--cd)}
.stpn[hidden]{display:none}
.stchs{display:flex;flex-wrap:wrap;gap:8px}
.stch{padding:10px 14px;border-radius:12px;border:1px solid var(--bd);background:transparent;color:inherit;font:inherit;cursor:pointer}
.stch.on{border-color:var(--g);background:rgba(var(--gr),.2);font-weight:700}
.stch:disabled{opacity:.35;cursor:not-allowed}
.stvrw canvas{width:100%;height:160px;border-radius:12px;display:block}
.stvrt{text-align:center;font-size:22px;margin:6px 0}
.stvrb{display:flex;gap:8px;margin:8px 0}.stvrb .btn{flex:1}
.stbn{position:absolute;bottom:2px;inset-inline-start:4px;font-size:10px;background:rgba(0,0,0,.6);color:#fff;border-radius:8px;padding:0 5px}

