window.__ip=null;
window.addEventListener('beforeinstallprompt',function(e){e.preventDefault();window.__ip=e});
window.addEventListener('appinstalled',function(){window.__ip=null});

/* security + memory helpers */
(function(){var OK=['youtube.com','youtube-nocookie.com','blogger.com','blogspot.com','google.com','archive.org'];
function ok(o){try{if(o===location.origin)return true;var u=new URL(o);if(u.protocol!=='https:')return false;return OK.some(function(d){return u.hostname===d||u.hostname.slice(-(d.length+1))==='.'+d})}catch(e){return false}}
window.ddOkOrigin=ok;
window.addEventListener('message',function(e){if(!ok(e.origin))e.stopImmediatePropagation()},true);
window.ddYT=function(fr,obj){try{var m=/^https:\/\/(www\.youtube(?:-nocookie)?\.com)\//.exec((fr&&fr.src)||'');if(m&&fr.contentWindow)fr.contentWindow.postMessage(JSON.stringify(obj),'https://'+m[1])}catch(e){}};
var OU=null;
window.stOuSet=function(u){if(OU){try{URL.revokeObjectURL(OU)}catch(e){}}OU=u||null;return u};
window.stCvFree=function(c){try{if(c){c.width=0;c.height=0}}catch(e){}};
})();
