function stSyDraw(){var cv=$('#stsyc');if(!cv||!STCA)return;var c=cv.getContext('2d'),W=cv.width,H=cv.height,pk=STCA.pk,d=STCA.buf.duration,N=stSyN();c.clearRect(0,0,W,H);STCA.buf.sil.forEach(function(x){c.fillStyle='rgba(200,60,60,.18)';c.fillRect(x[0]/d*W,0,(x[1]-x[0])/d*W,H)});for(var i=0;i<W;i++){var on=i/W>=STCA.s&&i/W<=STCA.e;c.fillStyle=on?stAcc():'rgba(128,128,128,.45)';var h=Math.max(1,pk[i]*H*.8);c.fillRect(i,(H-h)/2,1,h)}
 var mk=STCA.marks.slice().sort(function(p,q){return p-q});c.font='bold 13px sans-serif';c.textAlign='center';var prev=STCA.s*d;mk.concat([STCA.e*d]).forEach(function(m,i){c.fillStyle='rgba(255,255,255,.9)';c.fillText(i+1,(prev+m)/2/d*W,14);prev=m});mk.forEach(function(m){c.fillStyle='#e0452f';c.fillRect(m/d*W-1.5,0,3,H)});
 if(STSYP&&STSYP.pos!=null){c.fillStyle='#fff';c.fillRect(STSYP.pos/d*W-1,0,2,H)}var i2=$('#stsyi');if(i2)i2.textContent=STCA.name+' · '+((STCA.e-STCA.s)*d).toFixed(1)+'s · '+STCA.marks.length+' / '+(N-1)+' '+t('st_sy_mk')}
function stSyPlay(){if(STSYP){stSyStop();return}var b=STCA.buf,AC=window.AudioContext||window.webkitAudioContext,ac=new AC(),s=ac.createBufferSource();s.buffer=b;s.connect(ac.destination);var st=STCA.s*b.duration,en=STCA.e*b.duration;s.start(0,st,en-st);STSYP={ac:ac,s:s,st:st,t0:ac.currentTime,pos:st};s.onended=stSyStop;(function lp(){if(!STSYP)return;STSYP.pos=STSYP.st+(ac.currentTime-STSYP.t0);stSyDraw();requestAnimationFrame(lp)})()}
function stSyStop(){var p=STSYP;STSYP=null;if(p){try{p.s.onended=null;p.s.stop()}catch(e){}try{p.ac.close()}catch(e){}}stSyDraw()}
var STSD=null;
D.addEventListener('pointerdown',function(e){var cv=e.target;if(!cv||cv.id!='stsyc'||!STCA)return;var r=cv.getBoundingClientRect(),d=STCA.buf.duration,x=(e.clientX-r.left)/r.width*d,tol=14/r.width*d,bi=-1,bd=1e9;STCA.marks.forEach(function(m,i){var q=Math.abs(m-x);if(q<tol&&q<bd){bd=q;bi=i}});if(bi<0){if(STCA.marks.length<stSyN()-1){STCA.marks.push(x);bi=STCA.marks.length-1;STSD={i:bi,mv:true}}else return}else STSD={i:bi,mv:false};try{cv.setPointerCapture(e.pointerId)}catch(x2){}e.preventDefault();stSyDraw()});
D.addEventListener('pointermove',function(e){if(!STSD||!STCA)return;var cv=$('#stsyc');if(!cv)return;var r=cv.getBoundingClientRect(),d=STCA.buf.duration;STCA.marks[STSD.i]=Math.max(0,Math.min(d,(e.clientX-r.left)/r.width*d));STSD.mv=true;stSyDraw()});
