 navigator.mediaDevices.getUserMedia({audio:{noiseSuppression:!!STVO.ns,echoCancellation:!!STVO.ec,autoGainControl:!!STVO.ag}}).then(function(sm){var AC=window.AudioContext||window.webkitAudioContext,ac=new AC();try{ac.resume()}catch(e){}var src=ac.createMediaStreamSource(sm),gn=ac.createGain(),an=ac.createAnalyser(),dst=ac.createMediaStreamDestination(),hp=null;an.fftSize=1024;gn.gain.value=gain;if(STVO.lc){hp=ac.createBiquadFilter();hp.type='highpass';hp.frequency.value=80;src.connect(hp);hp.connect(gn)}else src.connect(gn);gn.connect(an);gn.connect(dst);var rec=new MediaRecorder(dst.stream),r={sm:sm,ac:ac,gn:gn,an:an,rec:rec,ch:[],paused:false,acc:0,t0:performance.now(),pk:0,hist:[]};STRV=r;STRM=true;rec.ondataavailable=function(e){if(e.data&&e.data.size)r.ch.push(e.data)};
