/* YouTube Data API v3 key (free): duration + exact publish time. Blank = hidden. */
var YT_KEY='',YC={},SV={},NS='dd-'+location.hostname.replace(/[^a-z0-9]/gi,'-');
function fmtN(n){try{return new Intl.NumberFormat(lang,{notation:'compact'}).format(n)}catch(e){return n}}
function ago(d){try{var s=(Date.now()-new Date(d))/1000,u=[['year',31536000],['month',2592000],['week',604800],['day',86400],['hour',3600],['minute',60]];for(var i=0;i<u.length;i++)if(s>=u[i][1])return new Intl.RelativeTimeFormat(lang,{numeric:'auto'}).format(-Math.floor(s/u[i][1]),u[i][0]);return new Intl.RelativeTimeFormat(lang,{numeric:'auto'}).format(0,'minute')}catch(e){return new Date(d).toLocaleDateString()}}
function dur(x){var m=x.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);if(!m)return'';var h=+m[1]||0,mi=+m[2]||0,se=+m[3]||0,z=function(n){return n<10?'0'+n:n};return h?h+':'+z(mi)+':'+z(se):mi+':'+z(se)}
function ytLoad(ids){ids=ids.filter(function(i){return i&&!YC[i]});if(!YT_KEY||!ids.length)return Promise.resolve();var ps=[];for(var c=0;c<ids.length;c+=50)ps.push(fetch('https://www.googleapis.com/youtube/v3/videos?part=snippet,contentDetails,statistics&id='+ids.slice(c,c+50).join(',')+'&key='+YT_KEY).then(function(r){return r.json()}).then(function(j){(j.items||[]).forEach(function(v){YC[v.id]={v:+v.statistics.viewCount,d:dur(v.contentDetails.duration),p:v.snippet.publishedAt}})}).catch(function(){}));return Promise.all(ps)}
function yt(ids){ytLoad(ids).then(function(){ids.forEach(function(id){var y=YC[id];if(!y)return;D.querySelectorAll('[data-d="'+id+'"]').forEach(function(d){d.textContent=y.d});D.querySelectorAll('[data-m="'+id+'"]').forEach(function(m){m.textContent=ago(y.p)})})})}
