function svGet(k){return SV[k]!=null?Promise.resolve(SV[k]):fetch(AB+'/get/'+NS+'/'+k).then(function(r){return r.ok?r.json():{value:0}}).then(function(j){return SV[k]=+j.value||0}).catch(function(){return 0})}
function svHit(k){var seen=[];try{seen=JSON.parse(sessionStorage.getItem('dd_seen')||'[]')}catch(e){}if(seen.indexOf(k)>=0)return svGet(k);seen.push(k);try{sessionStorage.setItem('dd_seen',JSON.stringify(seen))}catch(e){}return fetch(AB+'/hit/'+NS+'/'+k).then(function(r){return r.json()}).then(function(j){return SV[k]=+j.value||0}).catch(function(){return 0})}
function fillSV(){var els=[].slice.call(D.querySelectorAll('[data-sv]')).filter(function(x){return x.dataset.sv&&!x.textContent});if(!els.length||!window.IntersectionObserver)return;var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){io.unobserve(e.target);svGet(e.target.dataset.sv).then(function(v){e.target.textContent=fmtN(v)+' '+t('vw')})}})});els.forEach(function(x){io.observe(x)})}
