 if(!d){if(PTERR&&Date.now()-PTERR<30000)return null;ptLoad(dk).then(function(x){PTERR=0;if(x.tz)PTTZ=x.tz;ptTick()}).catch(function(){PTERR=Date.now();ptTick()});return null}
