/* --- per-account sync: settings follow the logged-in user to every device (TV) via Supabase Realtime --- */
function ptSub(){var o={};PTSYNC.forEach(function(k){o[k]=PTC[k]});return o}
function ptApply(cfg){if(!cfg||typeof cfg!='object')return;if(PTSYNC.every(function(k){return cfg[k]===undefined||JSON.stringify(cfg[k])==JSON.stringify(PTC[k])}))return;
 PTSYNC.forEach(function(k){if(cfg[k]!==undefined&&cfg[k]!==null)PTC[k]=cfg[k]});PTC.gap=Object.assign({},PTD0.gap,PTC.gap||{});PTC.adj=Object.assign({},PTD0.adj,PTC.adj||{});
 ptSave();PTTZ='';PTERR=0;ptPaint();var p=$('#ptp');if(PTOPEN&&p&&!p.hidden)ptPanel();ptView(cur)}
function ptRemoteLoad(){if(!SES)return;sbReq('GET','/prayer_display?select=cfg').then(function(a){if(a&&a[0]&&a[0].cfg&&Object.keys(a[0].cfg).length)ptApply(a[0].cfg);else ptPublish()}).catch(function(){})}
function ptPubSoon(){if(!SES)return;clearTimeout(PTPUB);PTPUB=setTimeout(ptPublish,600)}
function ptPublish(){if(!SES)return;sbReq('POST','/prayer_display?on_conflict=user_id',[{cfg:ptSub(),updated_at:new Date().toISOString()}],'resolution=merge-duplicates,return=minimal').catch(function(){})}
function ptSync(){ptRt();if(SES)ptRemoteLoad()}
function ptRt(){clearTimeout(PTRT);
 if(!SES){if(PTWS){var w0=PTWS;PTWS=null;try{w0.close()}catch(e){}}clearInterval(PTHB);return}
 if(PTWS||!window.WebSocket)return;
 sbEnsure().then(function(){if(PTWS||!SES)return;var ws,n=1,tk=SES.at;
  try{ws=new WebSocket('wss://'+SB_URL.replace(/^https:\/\//,'')+'/realtime/v1/websocket?apikey='+SB_KEY+'&vsn=1.0.0')}catch(e){return}
  PTWS=ws;
  ws.onopen=function(){ws.send(JSON.stringify({topic:'realtime:ptdisplay',event:'phx_join',payload:{config:{broadcast:{ack:false,self:false},presence:{key:''},postgres_changes:[{event:'*',schema:'public',table:'prayer_display'}],private:false},access_token:SES.at},ref:String(n++),join_ref:'1'}));
   clearInterval(PTHB);PTHB=setInterval(function(){try{ws.send(JSON.stringify({topic:'phoenix',event:'heartbeat',payload:{},ref:String(n++)}))}catch(e){}
    sbEnsure().then(function(){if(SES&&SES.at!==tk){tk=SES.at;ws.send(JSON.stringify({topic:'realtime:ptdisplay',event:'access_token',payload:{access_token:tk},ref:String(n++)}))}}).catch(function(){})},25000)};
  ws.onmessage=function(e){var m;try{m=JSON.parse(e.data)}catch(x){return}if(m.event=='postgres_changes'){var r=m.payload&&m.payload.data&&m.payload.data.record;if(r&&r.cfg)ptApply(r.cfg)}};
  ws.onclose=function(){clearInterval(PTHB);if(PTWS===ws)PTWS=null;if(SES)PTRT=setTimeout(ptRt,4000)};
  ws.onerror=function(){try{ws.close()}catch(e){}}}).catch(function(){PTRT=setTimeout(ptRt,8000)})}
function ptSetRow(){return'<div class="ck"><input type="checkbox" id="spw"'+(PTC.on!==0?' checked':'')+'><span>'+t('pt_w')+'</span></div>'}
D.addEventListener('change',function(e){var x=e.target;if(x&&x.id=='spw'){PTC.on=x.checked?1:0;ptSave();ptView(cur)}});
function ptInit(){var b=$('#pwb');if(b)b.addEventListener('click',function(){go(Object.assign({},cur,{o:'pt'}))});setInterval(ptTick,1000);ptTick()}

